let record=safeRead('ironward-campaign-v1',{stars:[0,0,0,0,0]});if(!Array.isArray(record.stars)||record.stars.length!==5)record={stars:[0,0,0,0,0]};record.stars=record.stars.map(s=>Number.isInteger(s)&&s>=0&&s<=3?s:0);
