function sound(type){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;if(type==='shoot'&&now-lastSound<.07)return;lastSound=now;const g=audio.createGain();g.connect(audio.destination);if(['blast','kill','strike','missile','breach'].includes(type)){if(!noise){noise=audio.createBuffer(1,audio.sampleRate*.5,audio.sampleRate);const a=noise.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*(1-i/a.length)}const n=audio.createBufferSource(),filter=audio.createBiquadFilter();n.buffer=noise;filter.type='lowpass';filter.frequency.value=type==='strike'?600:1400;n.connect(filter);filter.connect(g);g.gain.setValueAtTime(type==='strike'?.14:.055,now);g.gain.exponentialRampToValueAtTime(.001,now+.4);n.start();n.stop(now+.45)}else{const o=audio.createOscillator();o.type=type==='shoot'?'triangle':'sine';o.connect(g);const freq={shoot:180,build:580,upgrade:850,hit:240,wave:150,won:920,lost:100,frost:700}[type]||400;o.frequency.setValueAtTime(freq,now);o.frequency.exponentialRampToValueAtTime(freq*(type==='shoot'?.3:1.4),now+.12);g.gain.setValueAtTime(.025,now);g.gain.exponentialRampToValueAtTime(.001,now+.17);o.start();o.stop(now+.19)}}catch{}}
